#include <stdio.h>
#include <stdint.h>

static uint64_t fib_u64(unsigned n) {
    uint64_t f = 0, g = 1;
    int started = 0;
    int i;
    for (i = 63; i >= 0; i--) {
        uint64_t c, d;
        if (!started) {
            if (((n >> i) & 1u) == 0) continue;
            started = 1;
        }
        c = f * ((g << 1) - f);
        d = f * f + g * g;
        printf("  i=%d bit=%llu c=%llu d=%llu\n", i, (unsigned long long)((n>>i)&1u), (unsigned long long)c, (unsigned long long)d);
        if ((n >> i) & 1u) { f = d; g = c + d; }
        else               { f = c; g = d; }
    }
    return f;
}
int main(void){ printf("n=1 -> %llu\n", (unsigned long long)fib_u64(1)); return 0; }
EOF
